import { spawnSync } from 'node:child_process';
import fs from 'node:fs';

const child = `
process.stdin.on('error', (e) => process.stderr.write('ERR ' + e.code + '\\n'));
process.stdin.on('data', () => process.stderr.write('data\\n'));
process.stdin.on('end', () => process.stderr.write('end\\n'));
(async () => { try { for await (const c of process.stdin) {} process.stderr.write('iter-done\\n'); } catch (e) { process.stderr.write('iter-err ' + e.code + '\\n'); } })();
`;
const fd = fs.openSync('/tmp', 'r');
const r = spawnSync(process.execPath, ['--input-type=module', '-e', child], { stdio: [fd, 'pipe', 'pipe'], encoding: 'utf8' });
process.stdout.write(JSON.stringify([r.status, r.stderr]) + '\n');

