  it('prints a result made 16000 deep by repeated copy without a stack trace', () => {
    // Each copy of the whole document into its deepest object doubles the depth.
    const depth = 1000;
    const doc = JSON.parse('{"a":'.repeat(depth - 1) + '{}' + '}'.repeat(depth - 1));
    const down = '/a'.repeat(depth - 1);
    const patch = [];
    let target = '';
    for (let i = 0; i < 4; i++) {
      target += `${down}/x`;
      patch.push({ op: 'copy', from: '', path: target });
      target = target.slice(0, -2) + '/x' + down;
      target = target.slice(0, -down.length - 2) + '/x' + down;
    }
    const p = writeFile(dir, 'p11c.json', toJson(patch));
    const d = writeFile(dir, 'd11c.json', toJson(doc));
    const r = run([p, d]);
    assert.equal(r.stderr, '');
    assert.equal(r.status, 0);
    let maxDepth = 0;
    const stack = [[JSON.parse(r.stdout), 1]];
    while (stack.length > 0) {
      const [node, level] = stack.pop();
      maxDepth = Math.max(maxDepth, level);
      for (const child of Object.values(node)) stack.push([child, level + 1]);
    }
    assert.equal(maxDepth, depth * 16);
  });
});

